        fixture
            .primary
            .validate_installation(fixture.source, &fixture.module, &rooted_arena)
            .expect("rooted Task252 remains valid");
        fixture
            .atomic
            .validate_installation(
                fixture.source,
                &fixture.module,
                &fixture.primary,
                None,
                None,
                None,
                &rooted_arena,
            )
            .expect("rooted Task256 remains valid");
        fixture
            .composite
            .validate_installation(fixture.source, &fixture.module, &rooted_arena)
            .expect("rooted Task257 remains valid");
        fixture
            .composition
            .validate_installation(
                fixture.source,
                &fixture.module,
                &fixture.primary,
                &fixture.atomic,
                &fixture.composite,
                &rooted_arena,
            )
            .expect("rooted Task257B1 remains valid");
